  Hypothesis TST : ltac2:(zQ "30!hv1!pb!ll1@4$2$1?1m@2$0?2TH+qv0@2$0?2TH+sm0").

  Ltac prep :=
    unfold kNumClasses, kSpaceSize, kPageSize, kFreeArrayOffset, kUserMapSize, AHI_LO, AIMG_TOP, AINST, REGIONINFO_SIZE in *;
