      (MS (mkR ra (Z_to_bv 64 (bv_unsigned sp + -48)) gp tp t0 t1 t2 (wz cb) (wz mhdr) (wz sb) (wz (sb + 2^37)) (wz c) (wz c) (wz (mhdr - sb)) (wz csz) x16 x17
